package com.citygo;
import com.citygo.report.ReportService;
import com.citygo.cart.service.*;
import com.citygo.booking.service.BookingService;
import com.citygo.payment.service.PaymentService;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import java.io.ByteArrayInputStream;
import java.time.*;
import static org.assertj.core.api.Assertions.*;
import static org.springframework.http.MediaType.APPLICATION_JSON;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class ReportReorderAuditIntegrationTest extends P2Fixtures {
 @Autowired ReportService reports;@Autowired BookingService booking;@Autowired PaymentService payments;@Autowired ReorderService reorder;@Autowired CartService cart;
 long uid,sid,order;String ut,at;
 @BeforeEach void fixture()throws Exception{uid=insertUser("reportuser","secret123","USER",true);insertUser("reportadmin","secret123","ADMIN",true);ut=loginToken("reportuser","secret123");at=loginToken("reportadmin","secret123");sid=session(20,1000);order=booking.create(uid,"report-original-key",request(contact(uid),line("SESSION",sid,1))).order().id();}
 @Test void shanghaiCrossDayRefundIsNegativeOnRefundDayAndPackageNotDuplicated(){long pid=pkg(1500,sid);long c=jdbcTemplate.queryForObject("SELECT id FROM contacts WHERE user_id=?",Long.class,uid);long other=booking.create(uid,"report-package-key",request(c,line("PACKAGE",pid,2))).order().id();payments.pay(uid,order,"SUCCESS");payments.pay(uid,other,"SUCCESS");payments.refund(uid,order,"跨日退款");
 jdbcTemplate.update("UPDATE payment_attempts SET paid_at='2026-06-01 16:00:00'");jdbcTemplate.update("UPDATE orders SET paid_at='2026-06-01 16:00:00',created_at='2026-06-01 16:00:00'");jdbcTemplate.update("UPDATE refunds SET success_at='2026-06-02 16:00:00'");var r=reports.report(LocalDate.parse("2026-06-01"),LocalDate.parse("2026-06-03"));assertThat(r.days().get(0).paidCents()).isZero();assertThat(r.days().get(1).paidCents()).isEqualTo(4000);assertThat(r.days().get(1).reservedPeople()).isEqualTo(3);assertThat(r.days().get(2).refundedCents()).isEqualTo(1000);assertThat(r.days().get(2).netCents()).isEqualTo(-1000);assertThat(r.rankings()).hasSize(2);assertThat(r.rankings().stream().mapToLong(ReportService.Ranking::salesCents).sum()).isEqualTo(4000);}
 @Test void exportHasNumericAmountsAndEscapesFormulaNames()throws Exception{payments.pay(uid,order,"SUCCESS");jdbcTemplate.update("UPDATE order_items SET name='=HYPERLINK(123)' WHERE order_id=?",order);LocalDate day=LocalDate.now(ZoneId.of("Asia/Shanghai"));var r=mockMvc.perform(get("/api/admin/reports/export").header("Authorization",bearer(at)).param("from",day.toString()).param("to",day.toString())).andExpect(status().isOk()).andReturn();try(var x=new XSSFWorkbook(new ByteArrayInputStream(r.getResponse().getContentAsByteArray()))){assertThat(x.getNumberOfSheets()).isEqualTo(3);assertThat(x.getSheetAt(0).getRow(1).getCell(1).getNumericCellValue()).isEqualTo(1000);var cell=x.getSheetAt(1).getRow(1).getCell(2);assertThat(cell.getCellType()).isEqualTo(org.apache.poi.ss.usermodel.CellType.STRING);assertThat(cell.getStringCellValue()).startsWith("'=");}assertThat(ReportService.safeCell(" 	+SUM(1)")).startsWith("'");}
 @Test void operatorCanExportButCannotReadAdministratorAudit()throws Exception{insertUser("reportop","secret123","OPERATOR",true);String op=loginToken("reportop","secret123");mockMvc.perform(get("/api/admin/audit").header("Authorization",bearer(op))).andExpect(status().isForbidden());mockMvc.perform(get("/api/admin/reports").header("Authorization",bearer(op)).param("from","2026-06-01").param("to","2026-06-01")).andExpect(status().isOk());}
 @Test void reportPermissionsAndDateBounds()throws Exception{mockMvc.perform(get("/api/admin/reports").header("Authorization",bearer(ut)).param("from","2026-01-01").param("to","2026-01-01")).andExpect(status().isForbidden());mockMvc.perform(get("/api/admin/reports").header("Authorization",bearer(at)).param("from","2026-01-01").param("to","2026-12-31")).andExpect(status().isBadRequest());mockMvc.perform(get("/api/admin/reports/export").param("from","2026-01-01").param("to","2026-01-01")).andExpect(status().isUnauthorized());}
 @Test void reorderUsesCurrentPriceAndSkipsInvalidInsteadOfRollingBackValid(){long second=session(20,2000);long c=jdbcTemplate.queryForObject("SELECT id FROM contacts WHERE user_id=?",Long.class,uid);long mixed=booking.create(uid,"report-reorder-key",request(c,line("SESSION",sid,1),line("SESSION",second,1))).order().id();jdbcTemplate.update("UPDATE sessions SET price_cents=3300 WHERE id=?",sid);jdbcTemplate.update("UPDATE sessions SET status='OFF_SALE' WHERE id=?",second);var r=reorder.reorder(uid,mixed);assertThat(r.added()).isEqualTo(1);assertThat(r.skipped()).hasSize(1);assertThat(cart.list(uid)).hasSize(1);assertThat(cart.list(uid).getFirst().product().unitPriceCents()).isEqualTo(3300);assertThat(jdbcTemplate.queryForObject("SELECT total_cents FROM orders WHERE id=?",Integer.class,mixed)).isEqualTo(3000);}
 @Test void reorderCannotAccessOtherUserAndDoesNotDuplicatePayment(){long other=insertUser("outsider","secret123","USER",true);assertThatThrownBy(()->reorder.reorder(other,order)).isInstanceOf(com.citygo.common.exception.BizException.class);assertThat(cart.list(other)).isEmpty();reorder.reorder(uid,order);assertThat(count("payment_attempts")).isZero();assertThat(count("orders")).isEqualTo(1);}
 @Test void successfulAndFailedOperationsAreAuditedWithoutSensitiveInput()throws Exception{String req="{\"categoryType\":\"ACTIVITY\",\"name\":\"secret-token-password-contact-13800000000\",\"sortOrder\":0}";var r=mockMvc.perform(post("/api/admin/categories").header("Authorization",bearer(at)).contentType(APPLICATION_JSON).content(req)).andExpect(status().isOk()).andReturn();long id=objectMapper.readTree(r.getResponse().getContentAsString()).path("data").path("id").asLong();mockMvc.perform(delete("/api/admin/categories/{id}",999999L).header("Authorization",bearer(at))).andExpect(status().isNotFound());assertThat(jdbcTemplate.queryForObject("SELECT COUNT(*) FROM audit_logs WHERE success=1",Integer.class)).isEqualTo(1);assertThat(jdbcTemplate.queryForObject("SELECT COUNT(*) FROM audit_logs WHERE success=0",Integer.class)).isEqualTo(1);assertThat(jdbcTemplate.queryForList("SELECT summary FROM audit_logs",String.class)).allSatisfy(s->assertThat(s).doesNotContain("secret","13800000000",at));mockMvc.perform(get("/api/admin/audit").header("Authorization",bearer(ut))).andExpect(status().isForbidden());assertThat(id).isPositive();assertThat(jdbcTemplate.queryForObject("SELECT created_by FROM categories WHERE id=?",Long.class,id)).isEqualTo(jdbcTemplate.queryForObject("SELECT id FROM users WHERE username='reportadmin'",Long.class));}
}
